#!/usr/bin/env node
import { readFile, writeFile } from 'node:fs/promises';
import { resolve } from 'node:path';

export const bootstrapOwner = '@sunnykgupta';

export function renderCodeowners(owner = bootstrapOwner) {
  return `# This file is generated by .github/scripts/generate-codeowners.mjs. Do not edit directly.\n# Bootstrap O1 (program/release) and O2 (security) principal: ${owner}.\n# O1 and O2 remain separate authorities even while assigned to one principal.\n\n* ${owner}\n/.github/ ${owner}\n/governance/ ${owner}\n/work/ ${owner}\n/docs/ ${owner}\n/integrations/ ${owner}\n`;
}

async function main() {
  const outputPath = resolve(process.cwd(), '.github/CODEOWNERS');
  const expected = renderCodeowners();
  const checkOnly = process.argv.includes('--check');

  if (checkOnly) {
    const actual = await readFile(outputPath, 'utf8');
    if (actual !== expected) {
      throw new Error('CODEOWNERS is out of date; run node .github/scripts/generate-codeowners.mjs.');
    }
    console.log('CODEOWNERS matches the bootstrap owner contract.');
    return;
  }

  await writeFile(outputPath, expected);
  console.log('Wrote .github/CODEOWNERS.');
}

if (import.meta.url === `file://${process.argv[1]}`) {
  main().catch((error) => {
    console.error(error.message);
    process.exitCode = 1;
  });
}
